#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Al-othmany Sender 3.5.6 FINAL ALL-IN-ONE

Single upload patch for the Android repository.
Includes the full 3.5.5 base when needed, then applies 3.5.6:
- smaller one-mode dashboard (Day/Night selector removed)
- real Keep Screen Awake switch
- manual Resume after leaving WhatsApp; no forced reopen
- Request -> X/Back once -> direct next link
- stricter REQUESTED verification / accurate counters
- Samsung Dual Messenger DUAL_APP user 95 fallback
- smaller centered settings window
- zero artificial inter-link delay retained

Accepted source states: 3.5.0 .. 3.5.6
Final: versionCode 356 / versionName 3.5.6
"""
from pathlib import Path
import base64, re, traceback
ROOT=Path.cwd()
if not (ROOT/'app').is_dir():
    raise SystemExit('ERROR: run from Android repository root')
BASE355_B64=''
FIX356_B64=''

def run_payload(label,payload):
    print('\n'+'='*76)
    print(label)
    print('='*76)
    src=base64.b64decode(payload).decode('utf-8')
    ns={'__name__':'__main__','__file__':f'<embedded:{label}>'}
    try:
        exec(compile(src,ns['__file__'],'exec'),ns,ns)
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        raise SystemExit(f'ERROR while applying {label}')

def version_code():
    s=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
    m=re.search(r'versionCode\s*=\s*(\d+)',s)
    return int(m.group(1)) if m else -1

vc=version_code()
if vc < 355:
    run_payload('STEP 1/2 - APPLY COMPLETE 3.5.5 BASE',BASE355_B64)
elif vc in (355,356):
    print(f'Source versionCode={vc}; 3.5.5 base stage not required.')
else:
    raise SystemExit(f'ERROR: unsupported future versionCode={vc}')

run_payload('STEP 2/2 - APPLY 3.5.6 MANUAL-RESUME CONTINUITY',FIX356_B64)

build=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
main=(ROOT/'app/src/main/java/com/althmany/groupmanager/ui/MainActivity.kt').read_text(encoding='utf-8')
layout=(ROOT/'app/src/main/res/layout/activity_main.xml').read_text(encoding='utf-8')
acc=(ROOT/'app/src/main/java/com/althmany/groupmanager/accessibility/QuickJoinAccessibilityService.kt').read_text(encoding='utf-8')
sh=(ROOT/'app/src/main/java/com/althmany/groupmanager/shizuku/ShizukuAutomationService.kt').read_text(encoding='utf-8')
required=[
    ('versionCode 356','versionCode = 356' in build),
    ('versionName 3.5.6','versionName = "3.5.6"' in build),
    ('compact 356','android:tag="compact356"' in layout),
    ('keep awake UI','exactKeepAwakeSwitch' in layout and 'exactKeepAwakeSwitch' in main),
    ('manual resume','Manual-resume contract' in main and 'manual-resume contract' in sh),
    ('dual user 95','userId == 95' in main),
    ('accurate request count','not counted as REQUESTED' in acc and 'VISUAL_REQUEST_UNVERIFIED' in sh),
]
missing=[name for name,ok in required if not ok]
if missing:
    raise SystemExit('ERROR: 3.5.6 final sanity failed: '+', '.join(missing))

print('\n'+'='*76)
print('✅ AL-OTHMANY SENDER 3.5.6 FINAL ALL-IN-ONE APPLIED')
print('='*76)
print('Run next:')
print('  python3 scripts/validate_source.py')
print('  bash scripts/compile_pure_kotlin.sh')
print('  bash scripts/run_pure_kotlin_regressions.sh')
print('  git diff --check')
print('  gradle --no-daemon --no-configuration-cache :app:assembleDebug --console=plain')
